insert into public.schedule_sources (id, rink_id, kind, url, label, approved, terms_checked, terms_note) values ('kent-public', 'kent', 'public', 'https://calendar.google.com/calendar/ical/juvuejlh2bvf020bhbe4m2h2og%40group.calendar.google.com/public/basic.ics', 'Kent Valley''s public skating calendar', true, null, 'Read 2026-11-22: the rink''s site has no terms page and its robots file allows reading. But the events come from Google, and calendar.google.com/robots.txt disallows every path but the home page, which Google''s terms tie to automated access. Not fetched until the owner chooses a route.');
